contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 x) public payable {
        uint256 balanceBefore = address(c).balance;
        uint256 pot = c.winnersPot(); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = address(c).balance;
        assert(pot == balanceBefore / 2 && balanceAfter == balanceBefore);
    }

    receive() external payable {}
}

