pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 x) internal {
        uint256 balanceBefore = address(c).balance;
        uint256 pot;
        try c.winnersPot() returns (uint256 __r) { pot = __r; } catch { return; }
        uint256 balanceAfter = address(c).balance;
        assertTrue(pot == balanceBefore / 2 && balanceAfter == balanceBefore);
    }

    function testFuzz_run(uint256 x) public {
        _run(x);
    }

    receive() external payable {}
}
